window.kbPageData["views/entry/k-84a1934394881b8b"] = {"key":"entry/k-84a1934394881b8b","state":{"route":"entry/k-84a1934394881b8b"},"node":{"id":"k-84a1934394881b8b","mode":"k","title":"授权国务院先制定行政法规","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2025 副省级 行测#22","国考 2025 行政执法 行测#21"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":1,"independentCount":1,"directorySummary":"《立法法》第十一条所列事项尚未制定法律时，全国人大及其常委会可以授权国务院就其中部分事项先制定行政法规。","review":{"title":"授权国务院先制定行政法规","type":"制度与规则","domain":"法律","definition":"《立法法》第十一条所列事项尚未制定法律时，全国人大及其常委会可以授权国务院就其中部分事项先制定行政法规。","explanation":"国务院须依授权决定行使权限。犯罪和刑罚、剥夺公民政治权利、限制人身自由的强制措施和处罚、司法制度等事项不得依此授权。辨认选项时既要看受权机关，也要看它获准制定哪一种规范。","basis":"据原题解析及《中华人民共和国立法法》编释。","references":[{"source":"legislation2023","location":"第十一条至第十五条"}],"questionEvidence":{"国考 2025 副省级 行测#22":"对其中的部分事项先制定行政法规","国考 2025 行政执法 行测#21":"对其中的部分事项先制定行政法规"},"related":["k-24a0f49999363e27"]}},"questions":{"国考 2025 副省级 行测#22":{"paper":"国考 2025 副省级 行测","n":22,"mod":"常识判断","src":["ffe12c35a46d4df574ec.pdf",4],"asrc":["ff0b352b44d417525086.pdf",8],"card":"674f78bd53285bae48f968ba","links":[{"id":"k-84a1934394881b8b","role":"直接考查","why":"据原题解析及《中华人民共和国立法法》编释。"}]},"国考 2025 行政执法 行测#21":{"paper":"国考 2025 行政执法 行测","n":21,"mod":"常识判断","src":["d8efe4e19862104d89c8.pdf",4],"asrc":["e2c4b1970d2b49eac0fd.pdf",7],"card":"d7084b5b64b0c57a6090095a","links":[{"id":"k-84a1934394881b8b","role":"直接考查","why":"据原题解析及《中华人民共和国立法法》编释。"}]}},"terms":{"k-24a0f49999363e27":{"id":"k-24a0f49999363e27","mode":"k","type":"制度与规则","title":"法律解释权与司法解释","qs":[],"count":2}},"references":{"legislation2023":{"name":"中华人民共和国立法法（2023年修正）","url":"https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/bgt/art/2025/art_4e6af5cd28844e98b847ac2d7c0487a4.html"}},"topics":[],"units":{"k-84a1934394881b8b":[["国考 2025 副省级 行测#22","国考 2025 行政执法 行测#21"]]}};
